<script setup>
import {ref,watch} from 'vue';
import {cabinetInterval} from '../shared/cabinet-arrange.mjs';
const props=defineProps({item:Object,presets:{type:Array,required:true},preview:Object,guideSnapping:Boolean}),emit=defineEmits(['duplicate','save','add','remove','preview','confirm','cancel','pointer','rotation','rotate','guideSnap']);
const previewKind=ref('');
function updatePreview(){if(previewKind.value)emit('preview',{kind:previewKind.value,point:{x:x.value,z:z.value},presetId:choice.value});}
function placePointer(kind){previewKind.value='';emit('pointer',{kind,point:{x:x.value,z:z.value},presetId:choice.value});}
function beginPreview(kind){previewKind.value=kind;updatePreview();}
watch(()=>props.preview,value=>{if(!value)previewKind.value='';});
const x=ref(0),z=ref(0),name=ref(''),choice=ref('');
watch(()=>props.item?.id,()=>{previewKind.value='';if(props.item){const b=cabinetInterval(props.item,'x');x.value=props.item.x+b.max-b.min+.1;z.value=props.item.z;}},{immediate:true});
watch(()=>props.presets,list=>{if(!list.some(p=>p.id===choice.value))choice.value='';},{deep:true});
</script>
<template><section aria-label="Furniture library"><h3>Furniture library</h3><label>New furniture X<input v-model.number="x" @input="updatePreview" type="number" step="0.01"></label><label>New furniture Z<input v-model.number="z" @input="updatePreview" type="number" step="0.01"></label><button :disabled="!item" @click="emit('duplicate',{x,z})">Duplicate selected cabinet</button><button :disabled="!item" @click="beginPreview('copy')">Preview cabinet copy</button><button :disabled="!item" @click="placePointer('copy')">Place copy in Plan</button><label>Furniture preset name<input v-model="name" maxlength="60"></label><button :disabled="!item||!name.trim()" @click="emit('save',name)">Save furniture preset</button><label v-if="presets.length">Furniture preset<select v-model="choice" @change="updatePreview" aria-label="Furniture preset"><option value="">Choose preset</option><option v-for="preset in presets" :key="preset.id" :value="preset.id">{{ preset.name }}</option></select></label><button :disabled="!choice" @click="emit('add',{id:choice,point:{x,z}})">Add cabinet from preset</button><button :disabled="!choice" @click="beginPreview('preset')">Preview furniture preset</button><button :disabled="!choice" @click="placePointer('preset')">Place preset in Plan</button><button :disabled="!choice" @click="emit('remove',choice)">Delete furniture preset</button><label class="snap-toggle"><input :checked="guideSnapping" type="checkbox" aria-label="Snap furniture to alignment guides" @change="emit('guideSnap',$event.target.checked)">Snap to alignment guides</label><div v-if="preview"><label>Placement rotation degrees<input :value="preview.candidate?.rotation??preview.request.rotation??0" type="number" step="15" @input="emit('rotation',Number($event.target.value))"></label><button @click="emit('rotate',-15)">Rotate placement −15°</button><button @click="emit('rotate',15)">Rotate placement +15°</button><p v-if="preview.candidate" data-testid="placement-coordinates">Preview X {{ preview.candidate.x.toFixed(3) }} · Z {{ preview.candidate.z.toFixed(3) }} m</p><p data-testid="placement-guide-count">Placement guides: {{ preview.guides?.length||0 }} · rotation {{ preview.candidate?.rotation??0 }}°</p><p v-for="guide in preview.guides" :key="guide.axis" class="hint">{{ guide.axis.toUpperCase() }} {{ guide.candidateEdge }} near {{ guide.referenceName }} {{ guide.referenceEdge }}</p><p data-testid="furniture-library-preview">{{ preview.valid ? 'Preview valid' : preview.error }}</p><button :disabled="!preview.valid" @click="emit('confirm')">Confirm furniture placement</button><button @click="emit('cancel')">Cancel furniture preview</button></div><p class="hint">R rotates a preview +15°; Shift+R rotates −15° outside text fields. Guides use rotated world-axis bounds within 0.08 m; optional guide snapping applies after the grid. Preview ghosts are green for valid positions and red for invalid ones. Editing the model, selection or grid cancels previews; Escape cancels without changing history.</p><p class="hint">Plan placement follows the pointer; click a valid position to insert. Dragging does not insert; leaving the canvas or switching to 3D cancels. New positions use current grid snapping. Copies retain rotation and settings. Presets capture applied dimensions/material/stock, but create new IDs at rotation 0°. Existing cabinets stay independent. Save the project to retain presets.</p></section></template>
